import type { BeadCatalogue, DmcColor } from '@stitchcraft/types';

import raw from './bead-catalogues.json';

/**
 * Fuse-bead colour catalogues: Perler, Perler Mini, Hama Midi, Hama Mini,
 * Artkal S, Artkal C and Nabbi. Generated by tools/generate-bead-colors.js
 * from the MIT-licensed BeadColors lists; see source/README.md.
 */
export const BEAD_CATALOGUES: readonly BeadCatalogue[] = raw as BeadCatalogue[];

const byId = new Map(BEAD_CATALOGUES.map((c) => [c.id, c]));

export function findBeadCatalogue(id: string): BeadCatalogue | undefined {
  return byId.get(id);
}

/**
 * The colours a photo should be converted with: opaque beads only, unless
 * `includeSpecialFinishes`. Translucent, glitter, glow and similar beads look
 * nothing like their swatch once ironed, so matching a photo against them
 * gives surprising results.
 */
export function beadColorsForConversion(
  catalogue: BeadCatalogue,
  includeSpecialFinishes = false,
): DmcColor[] {
  return includeSpecialFinishes
    ? catalogue.colors
    : catalogue.colors.filter((c) => (c.finish ?? 'solid') === 'solid');
}
